from __future__ import annotations

from core.chat_models import chat_models_for, default_chat_model, read_block
from core.constants import ModelId
from models.provider import KNOWN_MODEL_IDS

BLOCK = """class ModelId:
    OLD = "x/old:free"  # Outside the block
    # OPENROUTER:BEGIN - generated by scripts/sync_models.sh, DO NOT EDIT
    LING = "inclusionai/ling-3.2-flash:free"  # inclusionAI: Ling 3.2 Flash (free)
    SUPER_VL = (
        "nvidia/nemotron-3.5-super-vl:free"  # NVIDIA: Nemotron 3.5 Super VL (free)
    )
    # OPENROUTER:END

    # OPENROUTER-EMBED:BEGIN - generated by scripts/sync_models.sh, DO NOT EDIT
    EMBED = "nvidia/nemotron-3-embed-1b:free"  # NVIDIA: Nemotron 3 Embed 1B (free)
    # OPENROUTER-EMBED:END
"""


def test_read_block_takes_one_line_and_wrapped_entries_of_that_block_only():
    assert read_block(BLOCK, "OPENROUTER") == {
        "inclusionai/ling-3.2-flash:free": "inclusionAI: Ling 3.2 Flash (free)",
        "nvidia/nemotron-3.5-super-vl:free": "NVIDIA: Nemotron 3.5 Super VL (free)",
    }


def test_openrouter_catalog_is_known_to_the_provider():
    models = chat_models_for("openrouter")
    assert models
    assert set(models) <= KNOWN_MODEL_IDS


def test_openrouter_catalog_has_chat_ids_with_labels_and_no_embed_or_rerank():
    models = chat_models_for("openrouter")
    assert models[ModelId.LING_3_2_FLASH] == "inclusionAI: Ling 3.2 Flash (free)"
    assert ModelId.NEMOTRON_3_EMBED_1B not in models
    assert ModelId.NEMOTRON_3_5_RERANK_8B not in models


def test_bedrock_catalog_is_the_anthropic_ids():
    assert chat_models_for("bedrock")[ModelId.CLAUDE_3_5_SONNET_V2] == "Claude 3.5 Sonnet v2"
    assert set(chat_models_for("bedrock")) == {
        ModelId.CLAUDE_3_HAIKU,
        ModelId.CLAUDE_3_5_HAIKU,
        ModelId.CLAUDE_3_5_SONNET_V1,
        ModelId.CLAUDE_3_5_SONNET_V2,
    }


def test_openai_and_unknown_providers_have_an_empty_catalog():
    assert chat_models_for("openai") == {}
    assert chat_models_for("nope") == {}


def test_default_is_first_chat_models_id_in_the_catalog():
    assert default_chat_model("openrouter", ["x/not-there:free", ModelId.PARTICLE_1]) == (
        ModelId.PARTICLE_1
    )


def test_default_falls_back_to_first_catalog_id_then_none():
    first = next(iter(chat_models_for("openrouter")))
    assert default_chat_model("openrouter", ["x/not-there:free"]) == first
    assert default_chat_model("openai", ["gpt-x"]) is None
